	/**
	 * Class for the Category combo box editor component.
	 * Category list model is refreshed each time cell editor is used.
	 */
	private class CategoryCellEditor : DefaultCellEditor {
		private GhidraComboBox<string> comboBox;
		private CategoryComboBoxModel comboModel;

		/* @SuppressWarnings("unchecked") */
		CategoryCellEditor() : base(new(new CategoryComboBoxModel()))
    {
			comboBox = (GhidraComboBox<string>) editorComponent;
			comboBox.setEditable(true);
			comboModel = (CategoryComboBoxModel) comboBox.getModel();
			setClickCountToStart(2);
		}

		/* @Override */
		public Component getTableCellEditorComponent(JTable table, object value, bool isSelected,
				int row, int column) {
			int viewIndex = table.convertColumnIndexToView(BookmarkTableModel.TYPE_COL);
			comboModel.refresh((string) table.getValueAt(row, viewIndex));
			return base.getTableCellEditorComponent(table, value, isSelected, row, column);
		}
	}

	/**
	 * Class for the combo box model to hold list of categories.
	 */
	private class CategoryComboBoxModel : DefaultComboBoxModel<string> {

		void refresh(string typeString) {
			removeAllElements();
			if (typeString != null) {
				BookmarkManager manager = program.getBookmarkManager();
				string[] categories = manager.getCategories(typeString);
				foreach (string element in categories) {
					addElement(element);
				}
			}
		}

	}

	private static class BookmarkRowObjectDeleteCommand : BackgroundCommand<Program> {
		private List<BookmarkRowObject> bookmarkList;

		public BookmarkRowObjectDeleteCommand(List<BookmarkRowObject> bookmarkList) : base("BookMark Delete", true, true, true)
    {
			this.bookmarkList = bookmarkList;
		}

		public bool doApplyTo(DomainObject obj, TaskMonitor monitor) {
			monitor.initialize(bookmarkList.size());
			BookmarkManager mgr = ((Program) obj).getBookmarkManager();
			foreach (BookmarkRowObject rowObject in bookmarkList) {
				Bookmark bookmark = mgr.getBookmark(rowObject.getKey());
				mgr.removeBookmark(bookmark);
				monitor.incrementProgress(1);
				if (monitor.isCancelled()) {
					break;
				}
			}
			return true;
		}

		/* @Override */
		public bool applyTo(Program program, TaskMonitor monitor) {
			bool wasEabled = program.isSendingEvents();
			try {
				program.setEventsEnabled(false);
				return doApplyTo(program, monitor);
			}
			finally {
				program.setEventsEnabled(wasEabled);
			}

		}
	}
}
